/* DUMB */
const timed_occ_fn=C=>0;
const readchar_queue=C=>C.literal("");
/* for rejecting attempts to use wizard mode commands
 * Also used in wizcmds.c  */
const unavailcmd=C=>C.literal("Unavailable command '%s'.");
/* for rejecting #if !SHELL, !SUSPEND */
const cmdnotavail=C=>C.literal("'%s' command not available.");
/* the #prevmsg command */
function doprev_message()
{
    NWC0(R172(C.windowprocs));
    return 0;
}

/* Count down by decrementing multi */
function timed_occupation()
{
    C.callProc((C.cell(C.timed_occ_fn,"int (*)(void)").value),"int (void)");
    if(Number(R103(C.gm)>C.i64(0))) ((W103(C.gm,C.i64((R103(C.gm)-1n))))+1n);
    return Number(R103(C.gm)>C.i64(0));
}

/* If you have moved since initially setting some occupations, they
 * now shouldn't be able to restart.
 *
 * The basic rule is that if you are carrying it, you can continue
 * since it is with you.  If you are acting on something at a distance,
 * your orientation to it must have changed when you moved.
 *
 * The exception to this is taking off items, since they can be taken
 * off in a number of ways in the intervening time, screwing up ordering.
 *
 *      Currently:      Take off all armor.
 *                      Picking Locks / Forcing Chests.
 *                      Setting traps.
 */
function reset_occupations()
{
    C.reset_remarm();
    C.reset_pick();
    C.reset_trapset();
}

/* If a time is given, use it to timeout this function, otherwise the
 * function times out by its own means.
 */
function set_occupation(fn,txt,xtime)
{
    xtime=C.i64(xtime);
    if(xtime) {
        (W104(C.go,C.functionPointer("timed_occupation")));
        (C.cell(C.timed_occ_fn,"int (*)(void)").value=fn);
    } else (W104(C.go,fn));
    (W106(C.go,txt));
    (W105(C.go,0));
    return;
}

